def _greedy(usable):
    """Minimum-cost maximum matching when only offer capacities bind."""
    match = {}
    used = {}
    for offer in sorted(range(len(usable)), key=lambda i: (usable[i][1], usable[i][0])):
        capacity = usable[offer][3]
        taken = 0
        while taken < capacity and _augment_slot(offer, usable, match):
            taken += 1
        if taken:
            used[offer] = taken
    cost = 0
    pairs = []
    for name, offer in match.items():
        pairs.append((name, usable[offer][0]))
        cost += usable[offer][1]
    return pairs, cost


def _flow(usable, neighbours, requests, request_nodes, live_requests,
          offer_nodes, live_offers):
    """General min-cost flow route honouring binding quota forests."""
    blocks = {}
    for name in sorted(neighbours):
        key = (requests[name]['group'], tuple(neighbours[name]))
        block = blocks.get(key)
        if block is None:
            blocks[key] = [name]
        else:
            block.append(name)
    members = [sorted(names) for names in blocks.values()]
    request_slot = {name: 1 + index for index, name in enumerate(live_requests)}
    block_base = 1 + len(live_requests)
    tree_base = block_base + len(members)
    offer_slot = {name: tree_base + index for index, name in enumerate(live_offers)}
    offer_base = tree_base + len(live_offers)
    sink = offer_base + len(usable)
    net = Network(sink + 1)
    for name in live_requests:
        parent = request_nodes[name]['parent']
        node = request_slot[name]
        if parent is None:
            net.add(0, node, request_nodes[name]['capacity'], 0)
        else:
            net.add(request_slot[parent], node, request_nodes[name]['capacity'], 0)
    for name in live_offers:
        parent = offer_nodes[name]['parent']
        node = offer_slot[name]
        if parent is None:
            net.add(node, sink, offer_nodes[name]['capacity'], 0)
        else:
            net.add(node, offer_slot[parent], offer_nodes[name]['capacity'], 0)
    arcs = []
    for index, names in enumerate(members):
        node = block_base + index
        net.add(request_slot[requests[names[0]]['group']], node, len(names), 0)
        arcs.append([])
    for index, item in enumerate(usable):
        net.add(offer_base + index, offer_slot[item[2]], item[3], 0)
    for index, names in enumerate(members):
        node = block_base + index
        width = len(names)
        for offer_index in neighbours[names[0]]:
            capacity = usable[offer_index][3]
            edge = net.add(node, offer_base + offer_index,
                           width if width < capacity else capacity,
                           usable[offer_index][1])
            arcs[index].append((edge, offer_index, net.cap[edge]))
    units, spent = min_cost_flow(net, 0, sink)
    cap = net.cap
    pairs = []
    for index, names in enumerate(members):
        taken = []
        for edge, offer_index, capacity in arcs[index]:
            used = capacity - cap[edge]
            if used > 0:
                taken.extend([usable[offer_index][0]] * used)
        for name, offer in zip(names, taken):
            pairs.append((name, offer))
    return pairs, spent


def _pair_graph(usable, neighbours, requests, request_nodes, offer_nodes):
    """Build the obligation network as a NetworkX digraph with integer data."""
    import networkx as nx

    graph = nx.DiGraph()
    source = ('S',)
    sink = ('T',)
    graph.add_node(source)
    graph.add_node(sink)
    for name, node in request_nodes.items():
        tail = source if node['parent'] is None else ('R', node['parent'])
        graph.add_edge(tail, ('R', name), capacity=node['capacity'], weight=0)
    for name, node in offer_nodes.items():
        head = sink if node['parent'] is None else ('O', node['parent'])
        graph.add_edge(('O', name), head, capacity=node['capacity'], weight=0)
    for request in neighbours:
        graph.add_edge(('R', requests[request]['group']), ('r', request),
                       capacity=1, weight=0)
    for index, item in enumerate(usable):
        graph.add_edge(('o', index), ('O', item[2]), capacity=item[3], weight=0)
    for request, offers in neighbours.items():
        for index in offers:
            graph.add_edge(('r', request), ('o', index), capacity=1,
                           weight=usable[index][1])
    return graph, source, sink


def _networkx_route(usable, neighbours, requests, request_nodes, offer_nodes):
    """Maximum-cardinality minimum-cost plan via the bundled NetworkX simplex."""
    import networkx as nx

    graph, source, sink = _pair_graph(usable, neighbours, requests, request_nodes,
                                      offer_nodes)
    flow = nx.max_flow_min_cost(graph, source, sink, capacity='capacity', weight='weight')
    pairs = []
    spent = 0
    for request in neighbours:
        outgoing = flow.get(('r', request))
        if not outgoing:
            continue
        for node, units in outgoing.items():
            if units and node[0] == 'o':
                pairs.append((request, usable[node[1]][0]))
                spent += units * usable[node[1]][1]
    return pairs, spent


